import 'rondleiding.dart';

/// De inhoud van de rondleiding: hoofdstukken en stappen, in zes talen.
///
/// Eén op één overgenomen uit de rondleiding op de website (`web/src/lib/rondleiding.ts`), zodat
/// een lid dat op zijn telefoon begint en later op de site kijkt hetzelfde verhaal herkent.
/// Richard 20-09-2026: "mis nog veel stappen die web wel heeft in app" — de app had er 30, het
/// web 94.
///
/// Wat NIET is overgenomen: de browserwidget en het partnerpaneel. Die bestaan alleen op de site.
///
/// Een stap zonder `zoek` toont zijn uitleg in het midden; dat is bewust, want niet alles is een
/// knop (een kaartlaag, een heel scherm). Een stap met `zoek` is altijd optioneel: is de knop er
/// niet (functie uit, ander toestel), dan slaan we hem stil over in plaats van een lege cirkel te
/// tonen.

const int _tabFeed = 0;
const int _tabVangsten = 1;
const int _tabBijtkans = 2;
const int _tabKaart = 3;
const int _tabMenu = 4;

final List<Hoofdstuk> hoofdstukken = [
  Hoofdstuk(
    id: "start", icoon: "👋",
    naam: tx("Eerste stappen", "First steps", "Erste Schritte", "Premiers pas", "Primeros pasos", "Pierwsze kroki"),
    samenvatting: tx("Wat is YessFish en waar vind je alles?", "What is YessFish and where is everything?", "Was ist YessFish und wo findest du alles?", "Qu’est-ce que YessFish et où trouver quoi ?", "¿Qué es YessFish y dónde está todo?", "Czym jest YessFish i gdzie co znajdziesz?"),
    stappen: [
      Stap(id: "start-welkom", tab: _tabFeed,
        titel: tx("Welkom", "Welcome", "Willkommen", "Bienvenue", "Bienvenido", "Witaj"),
        tekst: tx("YessFish is je visboek, je viskaart en je vismaten in één. In deze handleiding leggen we per hoofdstuk alles uit. Je kunt altijd stoppen en later verdergaan.", "YessFish is your logbook, your map and your buddies in one. This guide explains everything chapter by chapter. Stop any time and continue later.", "YessFish ist Fangbuch, Karte und Angelkumpels in einem. Diese Anleitung erklärt alles Kapitel für Kapitel.", "YessFish, c’est ton carnet, ta carte et tes copains en un. Ce guide explique tout, chapitre par chapitre.", "YessFish es tu diario, tu mapa y tus amigos en uno. Esta guía lo explica capítulo a capítulo.", "YessFish to dziennik, mapa i koledzy w jednym. Ten przewodnik wyjaśnia wszystko rozdział po rozdziale.")),
      Stap(id: "start-hulp", tab: _tabFeed, zoek: "hulp-knop", optioneel: true,
        titel: tx("Hulp, altijd bereikbaar", "Help, always there", "Hilfe, immer da", "L’aide, toujours là", "Ayuda, siempre a mano", "Pomoc zawsze pod ręką"),
        tekst: tx("Kom je er later niet uit? Tik rechtsboven op het vraagteken: de handleiding opent dan meteen bij het scherm waar je bent. De hele handleiding vind je via Menu, onderaan bij Account. Tik daar een hoofdstuk aan en je bladert er in zijn eigen scherm doorheen, met een plaatje bij elke stap.", "Stuck later on? Tap the question mark at the top right: the guide opens right at the screen you are on. The whole guide is under Menu, at the bottom under Account. Tap a chapter there and you page through it on its own screen, with a picture at every step.", "Später nicht weiter? Tippe oben rechts auf das Fragezeichen: die Anleitung öffnet sich genau beim Bildschirm, auf dem du bist. Die ganze Anleitung steht im Menü, unten unter Konto. Tippe dort ein Kapitel an und blättere es in seinem eigenen Bildschirm durch, mit einem Bild bei jedem Schritt.", "Bloqué plus tard ? Touche le point d'interrogation en haut à droite : le guide s'ouvre pile à l'écran où tu es. Le guide complet est dans le Menu, tout en bas sous Compte. Touche-y un chapitre et feuillette-le dans son propre écran, avec une image à chaque étape.", "¿Te atascas más adelante? Toca el signo de interrogación arriba a la derecha: la guía se abre justo en la pantalla en la que estás. La guía completa está en el Menú, abajo en Cuenta. Toca ahí un capítulo y lo hojeas en su propia pantalla, con una imagen en cada paso.", "Utkniesz później? Dotknij znaku zapytania w prawym górnym rogu: przewodnik otworzy się dokładnie przy ekranie, na którym jesteś. Cały przewodnik znajdziesz w Menu, na dole w sekcji Konto. Dotknij tam rozdziału i przewijaj go na własnym ekranie, z obrazkiem przy każdym kroku.")),
      Stap(id: "start-menu", tab: _tabMenu, zoek: "nav-balk", optioneel: true,
        titel: tx("Het menu", "The menu", "Das Menü", "Le menu", "El menú", "Menu"),
        tekst: tx("Onderin staat de balk met vijf knoppen: Feed, Vangsten, Bijtkans, Kaart en Menu. Achter Menu zit alles wat niet in de balk past. Open hem even, dan laat ik zien hoe hij is ingedeeld.", "At the bottom is the bar with five buttons: Feed, Catches, Bite forecast, Map and Menu. Behind Menu is everything that does not fit in the bar. Open it and I will show you how it is arranged.", "Unten ist die Leiste mit fünf Knöpfen: Feed, Fänge, Beißzeiten, Karte und Menü. Hinter Menü steht alles, was nicht in die Leiste passt. Öffne es, dann zeige ich dir die Einteilung.", "En bas, la barre à cinq boutons : Fil, Prises, Mordant, Carte et Menu. Derrière Menu se trouve tout ce qui ne tient pas dans la barre. Ouvre-le, je te montre l'organisation.", "Abajo está la barra con cinco botones: Muro, Capturas, Picada, Mapa y Menú. Tras Menú está todo lo que no cabe en la barra. Ábrelo y te enseño cómo está organizado.", "Na dole jest pasek z pięcioma przyciskami: Tablica, Połowy, Branie, Mapa i Menu. Za Menu jest wszystko, co nie mieści się w pasku. Otwórz je, a pokażę ci układ.")),
      Stap(id: "start-menu-inhoud", tab: _tabMenu,
        titel: tx("Zo is het ingedeeld", "How it is arranged", "So ist es eingeteilt", "Comment c’est rangé", "Cómo está organizado", "Jak to ułożone"),
        tekst: tx("Het menu staat nu open. Bovenaan je profiel met je dobbers en je cijfers. Daaronder Sociaal: meldingen, berichten, je vrienden, de ranglijst, de toplijst en clubs. Dan Mijn visserij met je vistijlen, de vistijl-tools, albums, uitrusting, toernooien, de wedstrijd, schone stek en de kaart. Daarna Hulpmiddelen: visherkenning, de soortengids, het weer, je visdocumenten en Mijn data. Vervolgens de Gids met verenigingen, winkels, betaalwateren, jachthavens en winacties, dan Partners, en onderaan Account met de Handleiding en je instellingen.", "The menu is open now. At the top your profile with your bobbers and your figures. Below that Social: notifications, messages, your friends, the ranking, the top list and clubs. Then My fishing with your fishing styles, the style tools, albums, tackle, tournaments, the contest, clean spot and the map. After that Tools: fish recognition, the species guide, the weather, your fishing documents and My data. Then the Guide with clubs, shops, paid waters, marinas and giveaways, then Partners, and at the bottom Account with the Guide and your settings.", "Das Menü ist jetzt offen. Oben dein Profil mit deinen Posen und deinen Zahlen. Darunter Sozial: Meldungen, Nachrichten, Freunde, Rangliste, Topliste und Clubs. Dann Mein Angeln mit Angelstilen, Stil-Werkzeugen, Alben, Ausrüstung, Turnieren, dem Wettbewerb, sauberer Stelle und der Karte. Danach Werkzeuge: Fischerkennung, Artenführer, Wetter, deine Angeldokumente und Meine Daten. Dann der Führer mit Vereinen, Läden, Zahlgewässern, Marinas und Gewinnspielen, danach Partner, und unten Konto mit der Anleitung und deinen Einstellungen.", "Le menu est ouvert. En haut ton profil avec tes flotteurs et tes chiffres. En dessous Social : notifications, messages, tes amis, le classement, le palmarès et les clubs. Puis Ma pêche avec tes styles, les outils de style, albums, matériel, tournois, le concours, poste propre et la carte. Ensuite Outils : reconnaissance, guide des espèces, météo, tes documents et Mes données. Puis le Guide avec associations, magasins, eaux payantes, ports et jeux-concours, ensuite Partenaires, et en bas Compte avec le Guide et tes réglages.", "El menú está abierto. Arriba tu perfil con tus boyas y tus cifras. Debajo Social: avisos, mensajes, tus amigos, la clasificación, la tabla de mejores y los clubes. Luego Mi pesca con tus estilos, las herramientas de estilo, álbumes, equipo, torneos, el concurso, sitio limpio y el mapa. Después Herramientas: reconocimiento, guía de especies, el tiempo, tus documentos y Mis datos. Luego la Guía con clubes, tiendas, aguas de pago, puertos y sorteos, después Socios, y abajo Cuenta con la Guía y tus ajustes.", "Menu jest otwarte. Na górze twój profil ze spławikami i twoimi liczbami. Niżej Społeczność: powiadomienia, wiadomości, znajomi, ranking, lista najlepszych i kluby. Dalej Moje wędkowanie: style, narzędzia stylu, albumy, sprzęt, turnieje, konkurs, czyste stanowisko i mapa. Potem Narzędzia: rozpoznawanie ryb, przewodnik gatunków, pogoda, dokumenty i Moje dane. Następnie Przewodnik z kołami, sklepami, łowiskami płatnymi, marinami i konkursami, potem Partnerzy, a na dole Konto z Przewodnikiem i ustawieniami.")),
    ]),
  Hoofdstuk(
