/// Alle stappen achter elkaar, zoals het lid ze doorloopt.
/// Alle stappen achter elkaar, hoofdstuk voor hoofdstuk.
///
/// In de fotostand kun je met `--dart-define=TOUR_ALLEEN=<id>,<id>` een handjevol stappen kiezen;
/// dan hoeft er na een schermwijziging niet twee uur aan afdrukken opnieuw gemaakt te worden.
/// Buiten de fotostand doet deze instelling niets.
List<Stap> alleStappen() {
  final alles = [for (final h in hoofdstukken) ...h.stappen];
  const alleen = String.fromEnvironment('TOUR_ALLEEN');
  if (alleen.isEmpty) return alles;
  final wil = alleen.split(',').map((e) => e.trim()).where((e) => e.isNotEmpty).toSet();
  final keuze = alles.where((s) => wil.contains(s.id)).toList();
  return keuze.isEmpty ? alles : keuze;
}
